import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

type Draft = Record<string, string>;

type Gap = { id?: string; requirement?: string };

type Pack = {
  completeness?: { stored?: number; required?: number; percent?: number };
  gaps?: Gap[];
  metrics?: { totalEmissionsKgCo2e?: number | null };
};

const FIELDS: { key: string; label: string; pillar: string; multiline?: boolean }[] = [
  { pillar: 'Governance', key: 'oversightBody', label: 'Who oversees climate-related risks' },
  { pillar: 'Governance', key: 'oversightCadence', label: 'How often that oversight happens' },
  { pillar: 'Governance', key: 'managementRole', label: 'Who in management assesses and manages the risks' },
  { pillar: 'Governance', key: 'inventoryOwner', label: 'Person responsible for the greenhouse-gas inventory' },
  { pillar: 'Governance', key: 'skillsAndInformationUse', label: 'How that information is used', multiline: true },
  { pillar: 'Strategy', key: 'physicalRisks', label: 'Physical risks, separated by commas', multiline: true },
  { pillar: 'Strategy', key: 'transitionRisks', label: 'Transition risks, separated by commas', multiline: true },
  { pillar: 'Strategy', key: 'opportunities', label: 'Climate-related opportunities, separated by commas', multiline: true },
  { pillar: 'Strategy', key: 'shortTermEffect', label: 'Short-term effect', multiline: true },
  { pillar: 'Strategy', key: 'mediumTermEffect', label: 'Medium-term effect', multiline: true },
  { pillar: 'Strategy', key: 'longTermEffect', label: 'Long-term effect', multiline: true },
  { pillar: 'Strategy', key: 'businessModelEffect', label: 'Effect on the business model', multiline: true },
  { pillar: 'Strategy', key: 'valueChainEffect', label: 'Effect on the value chain', multiline: true },
  { pillar: 'Strategy', key: 'currentFinancialEffect', label: 'Current financial effect', multiline: true },
  { pillar: 'Strategy', key: 'anticipatedFinancialEffect', label: 'Anticipated financial effect', multiline: true },
  { pillar: 'Strategy', key: 'resilienceCase', label: 'Resilience case the company has considered', multiline: true },
  { pillar: 'Risk management', key: 'identificationProcess', label: 'How risks are identified and assessed', multiline: true },
  { pillar: 'Risk management', key: 'prioritisationProcess', label: 'How risks are prioritised', multiline: true },
  { pillar: 'Risk management', key: 'enterpriseRiskIntegration', label: 'How this sits in the company risk process', multiline: true },
  { pillar: 'Metrics and targets', key: 'targetNote', label: 'Target note, when an SBTi record is not stored', multiline: true },
  { pillar: 'Metrics and targets', key: 'internalCarbonPriceInrPerTonne', label: 'Internal carbon price, INR per tonne CO2e' },
  { pillar: 'Metrics and targets', key: 'remunerationNote', label: 'Climate-related pay, when it exists', multiline: true },
  { pillar: 'Metrics and targets', key: 'capitalDeployedNote', label: 'Capital deployed on climate-related risks and opportunities', multiline: true },
  { pillar: 'Metrics and targets', key: 'industryMetricName', label: 'Industry metric name' },
  { pillar: 'Metrics and targets', key: 'industryMetricValue', label: 'Industry metric value' },
  { pillar: 'Metrics and targets', key: 'industryMetricUnit', label: 'Industry metric unit' },
  { pillar: 'IFRS S1', key: 'materialityNote', label: 'Why this disclosure is material', multiline: true },
  { pillar: 'IFRS S1', key: 'comparativeNote', label: 'Comparative period the reader should use', multiline: true },
  { pillar: 'IFRS S1', key: 'judgmentsNote', label: 'Judgments and estimation uncertainty', multiline: true },
  { pillar: 'IFRS S1', key: 'disclosureLocation', label: 'Where this disclosure sits next to the financial statements' },
];

const listText = (value: unknown) => (
  Array.isArray(value) ? value.filter(Boolean).join(', ') : (value == null ? '' : String(value))
);

const draftFromProfile = (profile: Record<string, unknown>): Draft => {
  const stored = (profile.tcfdIssbDisclosure && typeof profile.tcfdIssbDisclosure === 'object'
    ? profile.tcfdIssbDisclosure
    : {}) as Record<string, unknown>;
  const draft: Draft = {};
  FIELDS.forEach((field) => {
    draft[field.key] = field.key === 'physicalRisks'
      ? listText(stored.physicalRisks || profile.tcfdPhysicalRisks)
      : listText(stored[field.key]);
  });
  return draft;
};

const TcfdIssbDisclosureForm: React.FC<{
  exportProfile: Record<string, unknown>;
  pack?: Pack | null;
  onSaved: () => void;
}> = ({ exportProfile, pack, onSaved }) => {
  const [draft, setDraft] = useState<Draft>(() => draftFromProfile(exportProfile));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const pillars = useMemo(() => {
    const names: string[] = [];
    FIELDS.forEach((field) => {
      if (!names.includes(field.pillar)) names.push(field.pillar);
    });
    return names;
  }, []);
  const completeness = pack?.completeness;
  const gaps = pack && Array.isArray(pack.gaps) ? pack.gaps : [];

  const save = async () => {
    setSaving(true);
    setError(null);
    const physicalRisks = draft.physicalRisks.split(',').map((item) => item.trim()).filter(Boolean);
    const disclosure: Record<string, unknown> = { ...draft, physicalRisks };
    try {
      await ApiService.updateComplianceExportProfile({
        ...exportProfile,
        tcfdPhysicalRisks: physicalRisks,
        tcfdIssbDisclosure: disclosure,
      });
      onSaved();
    } catch (saveError) {
      setError(saveError instanceof Error ? saveError.message : 'The disclosure could not be saved.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Stack spacing={2}>
      <Alert severity={completeness && completeness.stored === completeness.required ? 'success' : 'info'}>
        {completeness
          ? `${completeness.stored} of ${completeness.required} IFRS S2 disclosures are stored${completeness.percent != null ? ` (${completeness.percent}%).` : '.'} Inventory kilograms stay as calculated.`
          : 'Save the company record, then refresh the pack. Inventory kilograms stay as calculated.'}
      </Alert>
      {pack?.metrics?.totalEmissionsKgCo2e != null ? (
        <Typography variant="body2">
          {`Inventory total used in this disclosure: ${pack.metrics.totalEmissionsKgCo2e} kg CO2e.`}
        </Typography>
      ) : null}
      {gaps.length > 0 ? (
        <Box>
          <Typography variant="subtitle2">Still to record</Typography>
          {gaps.slice(0, 8).map((gap) => (
            <Typography key={gap.id || gap.requirement} variant="body2" color="text.secondary">
              {gap.requirement}
            </Typography>
          ))}
        </Box>
      ) : null}
      {error ? <Alert severity="error">{error}</Alert> : null}
      {pillars.map((pillar) => (
        <Box key={pillar}>
          <Typography variant="subtitle1" sx={{ fontWeight: 800, mb: 1 }}>{pillar}</Typography>
          <Box sx={{ display: 'grid', gap: 1 }}>
            {FIELDS.filter((field) => field.pillar === pillar).map((field) => (
              <TextField
                key={field.key}
                size="small"
                label={field.label}
                value={draft[field.key] || ''}
                multiline={Boolean(field.multiline)}
                minRows={field.multiline ? 2 : undefined}
                onChange={(event) => setDraft((current) => ({ ...current, [field.key]: event.target.value }))}
              />
            ))}
          </Box>
        </Box>
      ))}
      <Button variant="contained" disabled={saving} onClick={() => { void save(); }} sx={{ alignSelf: 'flex-start' }}>
        {saving ? 'Saving' : 'Save TCFD / IFRS S2 disclosure'}
      </Button>
    </Stack>
  );
};

export default TcfdIssbDisclosureForm;
